#include <bits/stdc++.h>
using namespace std;

int characterReplacement(string s, int k) {
    unordered_map<char, int> count;
    int start = 0, top = 0, ans = 0;
    for (int i = 0; i < (int)s.size(); ++i) {
        top = max(top, ++count[s[i]]);
        while ((i - start + 1) - top > k) {
            --count[s[start]];
            ++start;
        }
        ans = max(ans, i - start + 1);
    }
    return ans;
}

